<?php
session_start(); require_once 'GEX-EC-05-SCRUM-Sprint-3-Desarrollo-ConfiguracionDeConexion-20261007-V1.0.php';
if (!isset($_SESSION['usuario_id']) || ($_SESSION['usuario_rol'] ?? '') !== 'Coordinador') { header('Location: GEX-EC-05-SCRUM-Sprint-3-Desarrollo-PanelPrincipal-20261007-V1.0.php'); exit(); }
$estado = $_GET['estado'] ?? ''; $prioridad = $_GET['prioridad'] ?? ''; $categoria = trim($_GET['categoria'] ?? '');
$where = []; $params = [];
if (in_array($estado, ['Nuevo', 'En Proceso', 'Resuelta', 'Cerrada'], true)) { $where[] = 'estado = ?'; $params[] = $estado; }
if (in_array($prioridad, ['Alta', 'Media', 'Baja'], true)) { $where[] = 'prioridad = ?'; $params[] = $prioridad; }
if ($categoria !== '') { $where[] = 'categoria = ?'; $params[] = $categoria; }
$whereSql = $where ? ' WHERE ' . implode(' AND ', $where) : '';
$stmt = $pdo->prepare("SELECT estado, COUNT(*) AS total FROM solicitudes{$whereSql} GROUP BY estado ORDER BY FIELD(estado, 'Nuevo', 'En Proceso', 'Resuelta', 'Cerrada')"); $stmt->execute($params); $porEstado = $stmt->fetchAll(PDO::FETCH_ASSOC);
$cicloWhere = $where ? $whereSql . " AND estado IN ('Resuelta', 'Cerrada')" : " WHERE estado IN ('Resuelta', 'Cerrada')";
$stmt = $pdo->prepare("SELECT TIMESTAMPDIFF(SECOND, fecha_creacion, fecha_actualizacion) AS ciclo FROM solicitudes{$cicloWhere}");
// El filtro se replica exactamente para que los indicadores sean reproducibles.
$stmt->execute($params); $ciclos = array_map('intval', $stmt->fetchAll(PDO::FETCH_COLUMN)); sort($ciclos); $n = count($ciclos); $mediana = $n ? ($n % 2 ? $ciclos[intdiv($n, 2)] : ($ciclos[$n / 2 - 1] + $ciclos[$n / 2]) / 2) : null;
function horasIndicador(?float $segundos): string { return $segundos === null ? 'Sin datos' : number_format($segundos / 3600, 1, ',', '.') . ' h'; }
?>
<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Indicadores - Soporte</title><link rel="stylesheet" href="GEX-EC-05-SCRUM-Sprint-3-Desarrollo-EstilosDeInterfaz-20261007-V1.0.css"></head><body><div class="dashboard-layout"><?php include 'GEX-EC-05-SCRUM-Sprint-3-Desarrollo-MenuDeNavegacion-20261007-V1.0.php'; ?><div class="main-wrapper"><header class="topbar"><div class="topbar-title"><h2>Indicadores del servicio</h2></div><div class="topbar-user"><span><strong><?php echo htmlspecialchars($_SESSION['usuario_nombre']); ?></strong></span><span class="user-badge">Coordinador</span><a href="GEX-EC-05-SCRUM-Sprint-3-Desarrollo-CierreDeSesion-20261007-V1.0.php" class="btn-logout">Cerrar Sesión</a></div></header><main class="content-area"><div class="page-heading"><div><h1>Resumen agregado</h1><p>Los datos no muestran ranking ni detalle individual.</p></div></div><form method="GET" class="search-form"><select name="estado"><option value="">Todos los estados</option><?php foreach (['Nuevo', 'En Proceso', 'Resuelta', 'Cerrada'] as $item): ?><option value="<?php echo $item; ?>" <?php echo $estado === $item ? 'selected' : ''; ?>><?php echo $item; ?></option><?php endforeach; ?></select><select name="prioridad"><option value="">Todas las prioridades</option><?php foreach (['Alta', 'Media', 'Baja'] as $item): ?><option value="<?php echo $item; ?>" <?php echo $prioridad === $item ? 'selected' : ''; ?>><?php echo $item; ?></option><?php endforeach; ?></select><input type="text" name="categoria" value="<?php echo htmlspecialchars($categoria); ?>" placeholder="Categoría"><button class="badge-btn" type="submit">Aplicar filtros</button><a href="GEX-EC-05-SCRUM-Sprint-3-Desarrollo-IndicadoresDeServicio-20261007-V1.0.php" class="back-link">Limpiar</a></form><div class="metric-grid"><div class="metric-card"><span>Solicitudes filtradas</span><strong><?php echo array_sum(array_column($porEstado, 'total')); ?></strong></div><div class="metric-card"><span>Tiempo mediano de ciclo</span><strong><?php echo horasIndicador($mediana); ?></strong></div></div><div class="ui-card"><h3>Volumen por estado</h3><table class="modern-table"><thead><tr><th>Estado</th><th>Volumen</th></tr></thead><tbody><?php if (!$porEstado): ?><tr><td colspan="2" class="empty-table">Sin datos para los filtros seleccionados.</td></tr><?php else: ?><?php foreach ($porEstado as $fila): ?><tr><td><?php echo htmlspecialchars($fila['estado']); ?></td><td><strong><?php echo (int) $fila['total']; ?></strong></td></tr><?php endforeach; ?><?php endif; ?></tbody></table></div></main></div></div></body></html>
